import{_ as e,o as s,c as a,ak as n}from"./chunks/framework.WYeQYp8i.js";const c=JSON.parse('{"title":"Customisation","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"guide/customisation/index.md","filePath":"guide/customisation/index.md","lastUpdated":1794612345000}'),t={name:"guide/customisation/index.md"};function r(l,i,o,h,d,p){return s(),a("div",null,[...i[0]||(i[0]=[n(`<h1 id="customisation" tabindex="-1">Customisation <a class="header-anchor" href="#customisation" aria-label="Permalink to &quot;Customisation&quot;">​</a></h1><h2 id="modifier-execution-order" tabindex="-1">Modifier execution order <a class="header-anchor" href="#modifier-execution-order" aria-label="Permalink to &quot;Modifier execution order&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Be careful when changing the modifier execution order. The default order is purposefully defined and changing it may lead to unexpected behaviour.</p><p>If you change the order of a modifier to the same order as another modifier, there is no guarantee of which one will run first.</p></div><p>Modifiers always run in a specific order, regardless of the order you specify them in the notation. This is determined by the modifier&#39;s <code>order</code> property, and works in ascending order.</p><p>However, sometimes the default order is not desired, because certain games require a slightly different order.</p><p>For example, Open Legend requires the <a href="https://openlegendrpg.com/core-rules/actions-attributes#advantage--disadvantage-are-only-applied-before-explosions" target="_blank" rel="noreferrer">keep modifier to be run <strong>before</strong> the explode modifier</a>. However, by default, the <a href="./../notation/modifiers.html#explode">explode modifier</a> runs first.</p><p>This is because the <a href="./../notation/modifiers.html#explode">explode modifier</a> has an order of <code>3</code>, and the <a href="./../notation/modifiers.html#keep">keep modifier</a> has an order of <code>6</code>.</p><p>Fortunately, you can modify the execution order for any modifier either <a href="#change-default-order">globally</a>, or on a <a href="#change-individual-instance-order">per-instance basis</a>.</p><h3 id="change-default-order" tabindex="-1">Change default order <a class="header-anchor" href="#change-default-order" aria-label="Permalink to &quot;Change default order&quot;">​</a></h3><p>To change the execution order when rolling string notations (e.g. <code>DiceRoll(&#39;4d6!kh1&#39;)</code>), you can set the default order for a modifier.</p><p>For modifier execution order in the current API, see <a href="./../../api/rpg-dice-roller/namespaces/modifiers/interfaces/ModifierHandler.html"><code>ModifierHandler</code></a> and its <a href="./../../api/rpg-dice-roller/namespaces/modifiers/interfaces/ModifierHandler.html#order"><code>order</code></a> property. The examples below still use the previous modifier classes and need updating.</p><p>You can change it like:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// set the explode modifier order to 7</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExplodeModifier.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// set the keep modifier order to 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KeepModifier.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Any new <code>ExplodeModifier</code>, and <code>KeepModifier</code> objects will now have the new orders. Other modifiers will retain their original order.</p><p>This also works with manually created <code>Modifier</code> objects:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> mod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ExplodeModifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Conflicting order values</p><p>When changing a modifier order, any modifiers with the same order value should be changed to a unique value.</p></div><h4 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h4><p>Using the <a href="https://openlegendrpg.com/core-rules/actions-attributes#advantage--disadvantage-are-only-applied-before-explosions" target="_blank" rel="noreferrer">Open Legend example</a>, we would need the <a href="./../notation/modifiers.html#keep">keep modifier</a> to run before the <a href="./../notation/modifiers.html#explode">explode modifier</a>.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// With the default order;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// roll the dice, explode any that roll a 4, then keep only the highest 4 rolls</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> roll</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DiceRoll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;8d4kh4!&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Set the keep modifier order to \`3\` (The current order for the explode modifier)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KeepModifier.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// The drop modifier should always run after the keep modifier, so set that to \`4\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DropModifier.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Set the explode modifier to run after keep and drop modifiers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExplodeModifier.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Order 4 and 5 are alreday used for the re-roll and unique modifiers.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// We need to change them as well, otherwise the order is ambiguous</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ReRollModifier.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UniqueModifier.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// With the new order;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// roll the dice, keep only the highest 4 rolls, then explode any that roll a 4</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> roll</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DiceRoll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;8d4kh4!&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="change-individual-instance-order" tabindex="-1">Change individual instance order <a class="header-anchor" href="#change-individual-instance-order" aria-label="Permalink to &quot;Change individual instance order&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Limitations</p><p>This will <strong>not</strong> affect modifiers created from rolling string notation, and is only useful if you are manually creating modifier instances.</p><p>To affect roll notations, change the <a href="#change-default-order">default order</a> instead.</p></div><p>You can change the order on an individual modifier object, by setting the non-static <code>order</code> property:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> mod1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ExplodeModifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mod1.order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>This only affects the object you have modified. Creating another <code>ExplodeModifier</code> will still use the <a href="#change-default-order">default order</a>.</p>`,25)])])}const g=e(t,[["render",r]]);export{c as __pageData,g as default};
